    use std::fs;
    use std::time::SystemTime;

    let search_patterns = [
        "./*.json",
        "./checkpoints/*.json",
        "./models/*.json",
        "./*.checkpoint.json",
    ];

    let mut candidates: Vec<(String, SystemTime)> = Vec::new();

    for pattern in &search_patterns {
        if let Ok(entries) = glob::glob(pattern) {
            for entry in entries.flatten() {
